1	//! Generic runner for phase-probed measurement examples: CLI
2	//! config, thread pinning, and a fixed-duration round-trip
3	//! drive loop over injected send/recv closures.
4	//!
5	//! - [`Cfg`] / [`CommonArgs`] — the runtime configuration and
6	//!   the shared clap flags (`-d`/`--duration`, `-t`/`--ticks`,
7	//!   `--decimals <n>`, `--depth <list>`) the binaries flatten
8	//!   into their own `Parser` structs; [`parse_pin`] for a
9	//!   `--pin MAIN,WORKER` value.
10	//! - [`LineBuf`] — a cache-line-aligned heap region sized at
11	//!   runtime, so a cell's ring depth is a parameter rather
12	//!   than a const.
13	//! - [`pin_to_cpu`] — sched_setaffinity pinning (Linux; no-op
14	//!   stub elsewhere).
15	//! - [`drive`] — the round-trip loop: send a counter, receive
16	//!   the echo; probing lives in the caller's closures.
17	//! - [`report`] — flavor header + the phase reports in trip
18	//!   order.
19	//! - [`perf`] (Linux) — per-process hardware event counters
20	//!   via `perf_event_open`, for cache-fill counting inside
21	//!   measurement cells.
22	//!
23	//! Deliberately not a benchmark harness: no adaptive loop
24	//! sizing, overhead calibration, or bench registry — for that
25	//! scale of machinery use iiac-perf.
26	
27	#[cfg(target_os = "linux")]
28	pub mod perf;
29	pub mod topo;
30	
31	use std::time::{Duration, Instant};
32	
33	use tprobe::TProbe;
34	
35	/// Sentinel available to callers as a shutdown message;
36	/// [`drive`]'s counter skips it so payload values never
37	/// collide with it.
38	pub const STOP: u64 = u64::MAX;
39	
40	/// Iterations between wall-clock checks in [`drive`], keeping
41	/// the per-iteration cost of `Instant::now` off the common
42	/// path.
43	const CLOCK_CHECK_EVERY: u64 = 4096;
44	
45	/// Bytes per cache line, the alignment [`LineBuf`] gives a
46	/// region. The ring crate's `CACHE_LINE_SIZE` is the same
47	/// number, and the cells assert the two agree.
48	pub const LINE_BYTES: usize = 64;
49	
50	/// One cache line of backing store, so a run of them is a
51	/// line-aligned region.
52	#[derive(Clone, Copy)]
53	#[repr(C, align(64))]
54	struct CacheLine([u8; LINE_BYTES]);
55	
56	/// A cache-line-aligned heap region of at least the bytes asked
57	/// for, zeroed, sized at runtime.
58	///
59	/// - The ring `init` functions take `&mut [u8]` and want it
60	///   line-aligned. A const stack array fixes the depth per
61	///   build, and this does not.
62	/// - Heap against stack changes nothing a cell measures: the
63	///   region is touched once at init and lives in cache after.
64	pub struct LineBuf(Vec<CacheLine>);
65	
66	impl LineBuf {
67	    /// A zeroed region of at least `bytes` bytes, rounded up to
68	    /// whole lines.
69	    pub fn new(bytes: u64) -> Self {
70	        let lines = bytes.div_ceil(LINE_BYTES as u64) as usize;
71	        LineBuf(vec![CacheLine([0; LINE_BYTES]); lines])
72	    }
73	
74	    /// The region as bytes, for a ring's `init`.
75	    pub fn as_mut_bytes(&mut self) -> &mut [u8] {
76	        // SAFETY: the Vec is a contiguous run of `len` lines of
77	        // initialised bytes, a `u8` view has no alignment
78	        // requirement, and the borrow of `self` keeps the Vec
79	        // alive and unaliased for the slice's lifetime.
80	        unsafe {
81	            core::slice::from_raw_parts_mut(
82	                self.0.as_mut_ptr() as *mut u8,
83	                self.0.len() * LINE_BYTES,
84	            )
85	        }
86	    }
87	}
88	
89	/// Runtime configuration for a probed measurement run, built
90	/// from the parsed CLI args.
91	pub struct Cfg {
92	    /// Wall-clock budget per flavor.
93	    pub duration: Duration,
94	    /// Ring depths to run, each a power of two, every cell
95	    /// repeated per depth.
96	    pub depths: Vec<u32>,
97	    /// `Some((main_cpu, worker_cpu))` pins both threads.
98	    pub pin: Option<(usize, usize)>,
99	    /// Report raw ticks instead of nanoseconds.
100	    pub ticks: bool,
101	    /// Fractional digits on report value columns.
102	    pub decimals: usize,
103	}
104	
105	/// The CLI flags shared by the probed measurement binaries;
106	/// `#[command(flatten)]` into each binary's `Parser` struct.
107	#[derive(clap::Args, Debug)]
108	pub struct CommonArgs {
109	    /// Wall-clock seconds per cell (each flavor × placement
110	    /// combination runs this long)
111	    #[arg(
112	        short = 'd',
113	        long = "duration",
114	        value_name = "SECS",
115	        default_value_t = 5.0
116	    )]
117	    pub duration: f64,
118	
119	    /// Report raw TSC ticks instead of nanoseconds
120	    ///
121	    /// Probes store hardware tick deltas; by default reports
122	    /// convert them to ns via the calibrated ticks-per-ns
123	    /// ratio. This flag shows the stored ticks unconverted.
124	    #[arg(short = 't', long)]
125	    pub ticks: bool,
126	
127	    /// Fractional digits on report value columns
128	    #[arg(long, value_name = "N", default_value_t = 1)]
129	    pub decimals: usize,
130	
131	    /// Ring depths (slots per ring) to run, comma-separated
132	    /// powers of two; every cell repeats per depth
133	    ///
134	    /// One message is ever in flight in a round-trip cell, so
135	    /// the depth changes how many seq words share a line and,
136	    /// at 1, whether the ring has any slack at all.
137	    #[arg(
138	        long,
139	        value_name = "LIST",
140	        value_delimiter = ',',
141	        default_value = "8",
142	        value_parser = parse_depth
143	    )]
144	    pub depth: Vec<u32>,
145	}
146	
147	impl CommonArgs {
148	    /// Build the runtime [`Cfg`], attaching the binary-specific
149	    /// `pin` (only `tp-cell` exposes one).
150	    pub fn to_cfg(&self, pin: Option<(usize, usize)>) -> Cfg {
151	        Cfg {
152	            duration: Duration::from_secs_f64(self.duration),
153	            depths: self.depth.clone(),
154	            pin,
155	            ticks: self.ticks,
156	            decimals: self.decimals,
157	        }
158	    }
159	}
160	
161	/// clap value parser for one `--depth` element: a power of two
162	/// from 1 up, the ring geometry every flavor accepts.
163	pub fn parse_depth(s: &str) -> Result<u32, String> {
164	    let d: u32 = s
165	        .trim()
166	        .parse()
167	        .map_err(|_| format!("depth is not a number: `{s}`"))?;
168	    if d == 0 || !d.is_power_of_two() {
169	        return Err(format!("depth must be a power of two from 1 up, got {d}"));
170	    }
171	    Ok(d)
172	}
173	
174	/// clap value parser for `--pin MAIN,WORKER`: two
175	/// comma-separated logical CPU numbers.
176	pub fn parse_pin(s: &str) -> Result<(usize, usize), String> {
177	    let (m, w) = s
178	        .split_once(',')
179	        .ok_or_else(|| format!("expected MAIN,WORKER (e.g. 0,1), got `{s}`"))?;
180	    let m = m
181	        .trim()
182	        .parse()
183	        .map_err(|_| format!("MAIN is not a CPU number: `{m}`"))?;
184	    let w = w
185	        .trim()
186	        .parse()
187	        .map_err(|_| format!("WORKER is not a CPU number: `{w}`"))?;
188	    Ok((m, w))
189	}
190	
191	/// Pin the calling thread to `cpu` via sched_setaffinity;
192	/// panics on failure (a run with a silently ignored pin would
193	/// report a mislabeled number).
194	#[cfg(target_os = "linux")]
195	pub fn pin_to_cpu(cpu: usize) {
196	    // SAFETY: cpu_set_t is a plain bitmask; CPU_ZERO/CPU_SET
197	    // initialize it fully before sched_setaffinity reads it.
198	    unsafe {
199	        let mut set: libc::cpu_set_t = std::mem::zeroed();
200	        libc::CPU_ZERO(&mut set);
201	        libc::CPU_SET(cpu, &mut set);
202	        let rc = libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), &set);
203	        assert_eq!(rc, 0, "sched_setaffinity({cpu}) failed");
204	    }
205	}
206	
207	/// Non-Linux stub: `--pin` becomes a no-op.
208	#[cfg(not(target_os = "linux"))]
209	pub fn pin_to_cpu(_cpu: usize) {}
210	
211	/// Reset the calling thread's affinity to every online CPU —
212	/// the undo for [`pin_to_cpu`], needed when one process runs
213	/// pinned and unpinned cells in sequence.
214	#[cfg(target_os = "linux")]
215	pub fn unpin_current() {
216	    // SAFETY: cpu_set_t is a plain bitmask; CPU_ZERO/CPU_SET
217	    // initialize it fully before sched_setaffinity reads it.
218	    unsafe {
219	        let mut set: libc::cpu_set_t = std::mem::zeroed();
220	        libc::CPU_ZERO(&mut set);
221	        let n = libc::sysconf(libc::_SC_NPROCESSORS_ONLN).max(1) as usize;
222	        for cpu in 0..n {
223	            libc::CPU_SET(cpu, &mut set);
224	        }
225	        let rc = libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), &set);
226	        assert_eq!(rc, 0, "sched_setaffinity(all) failed");
227	    }
228	}
229	
230	/// Non-Linux stub: affinity is untouched, so nothing to undo.
231	#[cfg(not(target_os = "linux"))]
232	pub fn unpin_current() {}
233	
234	/// A spin wait policy: hint and keep trying. Matches the
235	/// `on_full`/`on_empty` closure shape of the ring endpoints.
236	pub fn spin(_attempt: u32) -> bool {
237	    core::hint::spin_loop();
238	    true
239	}
240	
241	/// Drive `dur` worth of round trips: send the counter via
242	/// `send`, receive the echo via `recv`. Returns when the
243	/// budget is spent (checked every [`CLOCK_CHECK_EVERY`]
244	/// iterations). The counter skips [`STOP`] so callers can use
245	/// it as a shutdown sentinel afterwards.
246	///
247	/// All probing lives in the closures — the loop itself
248	/// measures nothing, so callers control exactly what each
249	/// probe brackets (and record into their histograms *after*
250	/// their phase-end tick reads, off the measured path).
251	pub fn drive(dur: Duration, mut send: impl FnMut(u64), mut recv: impl FnMut() -> u64) {
252	    let start = Instant::now();
253	    let mut counter: u64 = 0;
254	    loop {
255	        for _ in 0..CLOCK_CHECK_EVERY {
256	            counter = counter.wrapping_add(1);
257	            if counter == STOP {
258	                counter = 1;
259	            }
260	            send(counter);
261	            let v = recv();
262	            assert_eq!(v, counter, "echo mismatch");
263	        }
264	        if start.elapsed() >= dur {
265	            return;
266	        }
267	    }
268	}
269	
270	/// Print one flavor's header, then its phase reports in the
271	/// order given (conventionally trip order: main send → worker
272	/// recv → worker send → main recv).
273	pub fn report(flavor: &str, cfg: &Cfg, depth: u32, probes: impl IntoIterator<Item = TProbe>) {
274	    let pin = match cfg.pin {
275	        Some((m, w)) => format!("main={m},worker={w}"),
276	        None => "none".to_string(),
277	    };
278	    println!(
279	        "{flavor} round trip [duration={:.1}s pin={pin} depth={depth}]:",
280	        cfg.duration.as_secs_f64(),
281	    );
282	    for p in probes {
283	        p.report(cfg.ticks, cfg.decimals);
284	    }
285	}
