/// number, and the cells assert the two agree.
pub const LINE_BYTES: usize = 64;

/// One cache line of backing store, so a run of them is a
/// line-aligned region.
#[derive(Clone, Copy)]
#[repr(C, align(64))]
struct CacheLine([u8; LINE_BYTES]);

