1	//! Phase-probed 1p/1c round-trip measurement cells over the
2	//! zc-ring-x1 primitives.
3	//!
4	//! One **cell** is a main → worker → main round trip at a given
5	//! ring flavor and thread placement, driven for a fixed
6	//! duration; each protocol phase is measured by its own
7	//! [`TProbe`] and, on Linux, the cross-core cache-fill counters
8	//! are collected in-process (no perf(1) needed):
9	//!
10	//! - `main send` / `worker send` — the producer's reserve +
11	//!   fill + commit, including any stall acquiring peer-written
12	//!   cache lines. The ring is never full here (one message in
13	//!   flight, at any depth from 1 up), so no send ever waits
14	//!   for space.
15	//! - `worker recv` / `main recv` — the consumer's spin wait +
16	//!   read + release; these absorb the in-flight half trip.
17	//! - `… recv spin` / `… recv attempts` — the wait inside the
18	//!   recv phase, decomposed: spin time (first failed attempt →
19	//!   reserve success) and the attempt count, recorded only for
20	//!   reserves that actually waited.
21	//!
22	//! A **streaming cell** is the other shape: the producer sends
23	//! a counter as fast as the ring admits for a fixed duration
24	//! and the consumer drains it, the depth in play as slack, and
25	//! the fill counters divided by the messages moved say how
26	//! many lines crossed per message while streaming, the number
27	//! the round-trip cell cannot give.
28	//!
29	//! The binaries: `tp-cell` runs one cell and prints the probe
30	//! reports; `tp-matrix` runs every flavor × placement cell and
31	//! emits markdown tables; `tp-stream` runs the streaming cell
32	//! over the same matrix.
33	
34	use std::time::{Duration, Instant};
35	
36	use tp_runner::{LINE_BYTES, LineBuf, STOP, drive, pin_to_cpu, spin, unpin_current};
37	use tprobe::TProbe;
38	use tprobe::ticks;
39	use zc_ring_x1::{CACHE_LINE_SIZE, MpscRing, mpsc_region_size};
40	
41	// The runner's line-aligned regions must be aligned the way
42	// the rings want them.
43	const _: () = assert!(LINE_BYTES == CACHE_LINE_SIZE);
44	
45	/// Bytes a v0 region needs: the four-line header, then the
46	/// slots. v0 exports no size function of its own, its header
47	/// being a fixed shape.
48	fn v0_region_size(slot_size: u32, capacity: u32) -> u64 {
49	    size_of::<zc_ring_x1::Header>() as u64 + slot_size as u64 * capacity as u64
50	}
51	
52	/// The ring flavor a cell measures.
53	#[derive(Clone, Copy, PartialEq, Eq)]
54	pub enum Flavor {
55	    /// The SPSC v0 ring (`reserve_slot_with` both ends).
56	    Spsc,
57	    /// The SPSC v1 seam-word ring (same surface, per-slot seq).
58	    SpscV1,
59	    /// The SPSC v2 in-slot seq ring (same surface, the seq at
60	    /// the front of its slot).
61	    SpscV2,
62	    /// The MPSC ring at 1p/1c (`send_with` producers).
63	    Mpsc,
64	}
65	
66	/// Every flavor, in report order.
67	pub const FLAVORS: [Flavor; 4] = [Flavor::Spsc, Flavor::SpscV1, Flavor::SpscV2, Flavor::Mpsc];
68	
69	impl Flavor {
70	    /// Lowercase name for labels and CLI parsing.
71	    pub fn as_str(self) -> &'static str {
72	        match self {
73	            Flavor::Spsc => "spsc",
74	            Flavor::SpscV1 => "spsc-v1",
75	            Flavor::SpscV2 => "spsc-v2",
76	            Flavor::Mpsc => "mpsc",
77	        }
78	    }
79	
80	    /// The smallest depth the flavor's protocol runs at. The
81	    /// MPSC ring's committed and released seq values coincide
82	    /// at capacity 1 (`notes/bugs.md`), so its cells start at 2.
83	    pub fn min_depth(self) -> u32 {
84	        match self {
85	            Flavor::Mpsc => 2,
86	            _ => 1,
87	        }
88	    }
89	}
90	
91	/// The cache-fill counter totals for one cell (Linux; `None`
92	/// in [`CellResult`] when unavailable).
93	pub struct FillCounts {
94	    /// Demand fills served from another core's cache — the
95	    /// cross-core line-transfer signal.
96	    pub lcl_cache: u64,
97	    /// Demand fills served from the core's own L2.
98	    pub lcl_l2: u64,
99	    /// Demand fills served from local DRAM.
100	    pub lcl_dram: u64,
101	}
102	
103	/// One cell's outcome: the eight probes in trip order and the
104	/// fill counters.
105	pub struct CellResult {
106	    /// Trip order: main send, worker recv, worker recv spin,
107	    /// worker recv attempts, worker send, main recv, main recv
108	    /// spin, main recv attempts.
109	    pub probes: [TProbe; 8],
110	    /// Round trips completed (== every probe's phase count).
111	    pub rts: u64,
112	    /// Fill counters, when the platform provides them.
113	    pub fills: Option<FillCounts>,
114	}
115	
116	/// The three per-cell fill counters, opened before the worker
117	/// spawns so `inherit` covers it.
118	#[cfg(target_os = "linux")]
119	struct Fills {
120	    lcl_cache: tp_runner::perf::ProcessCounter,
121	    lcl_l2: tp_runner::perf::ProcessCounter,
122	    lcl_dram: tp_runner::perf::ProcessCounter,
123	}
124	
125	#[cfg(target_os = "linux")]
126	impl Fills {
127	    /// Open + enable all three; `None` (with a one-line note)
128	    /// where perf_event_open is unavailable.
129	    fn open() -> Option<Fills> {
130	        use tp_runner::perf::{
131	            ProcessCounter, ZEN2_FILLS_LCL_CACHE, ZEN2_FILLS_LCL_DRAM, ZEN2_FILLS_LCL_L2,
132	        };
133	        let open = |config| ProcessCounter::new_raw(config);
134	        match (
135	            open(ZEN2_FILLS_LCL_CACHE),
136	            open(ZEN2_FILLS_LCL_L2),
137	            open(ZEN2_FILLS_LCL_DRAM),
138	        ) {
139	            (Ok(mut lcl_cache), Ok(mut lcl_l2), Ok(mut lcl_dram)) => {
140	                lcl_cache.enable().ok()?;
141	                lcl_l2.enable().ok()?;
142	                lcl_dram.enable().ok()?;
143	                Some(Fills {
144	                    lcl_cache,
145	                    lcl_l2,
146	                    lcl_dram,
147	                })
148	            }
149	            (r, _, _) => {
150	                if let Err(e) = r {
151	                    eprintln!("note: fill counters unavailable ({e}); fills/RT will be absent");
152	                }
153	                None
154	            }
155	        }
156	    }
157	
158	    /// Disable and read the totals.
159	    fn finish(mut self) -> Option<FillCounts> {
160	        self.lcl_cache.disable().ok()?;
161	        self.lcl_l2.disable().ok()?;
162	        self.lcl_dram.disable().ok()?;
163	        Some(FillCounts {
164	            lcl_cache: self.lcl_cache.read().ok()?,
165	            lcl_l2: self.lcl_l2.read().ok()?,
166	            lcl_dram: self.lcl_dram.read().ok()?,
167	        })
168	    }
169	}
170	
171	/// The three probes each recv site records into.
172	struct RecvProbes {
173	    /// The whole recv phase (spin wait + read + release).
174	    phase: TProbe,
175	    /// Wait only: first failed attempt → reserve success;
176	    /// recorded only when the reserve actually waited.
177	    spin: TProbe,
178	    /// Attempt count per waiting reserve (counts probe).
179	    attempts: TProbe,
180	}
181	
182	impl RecvProbes {
183	    /// Build the three probes for the `side` ("main"/"worker")
184	    /// of a `flavor` run.
185	    fn new(flavor: Flavor, side: &str) -> Self {
186	        let flavor = flavor.as_str();
187	        RecvProbes {
188	            phase: TProbe::new(&format!("{flavor} {side} recv (reserve+release)")),
189	            spin: TProbe::new(&format!("{flavor} {side} recv spin (wait only)")),
190	            attempts: TProbe::new_counts(&format!("{flavor} {side} recv attempts")),
191	        }
192	    }
193	}
194	
195	/// One instrumented receive: `reserve` performs the endpoint's
196	/// reserve/read/release under a spin policy that must stamp
197	/// `spin_start` on its first failed attempt and keep `attempts`
198	/// current, then returns the received value. Records the phase
199	/// (and, when a wait happened, spin time + attempts) into
200	/// `probes` — unless the value is [`STOP`], which passes
201	/// through unrecorded.
202	fn instrumented_recv(
203	    probes: &mut RecvProbes,
204	    reserve: impl FnOnce(&mut u32, &mut u64) -> u64,
205	) -> u64 {
206	    let mut attempts: u32 = 0;
207	    let mut spin_start: u64 = 0;
208	    let s = ticks::read_ticks();
209	    let v = reserve(&mut attempts, &mut spin_start);
210	    let spin_end = if attempts > 0 { ticks::read_ticks() } else { 0 };
211	    let e = ticks::read_ticks();
212	    if v == STOP {
213	        return v;
214	    }
215	    probes.phase.record(e.wrapping_sub(s));
216	    if attempts > 0 {
217	        probes.spin.record(spin_end.wrapping_sub(spin_start));
218	        probes.attempts.record(attempts as u64);
219	    }
220	    v
221	}
222	
223	/// Run one measurement cell: pin (or unpin) the calling thread,
224	/// open the fill counters, drive `dur` worth of round trips at
225	/// `flavor` and ring `depth` with the worker on `pin.1`, and
226	/// return probes + counters. The caller's thread affinity is
227	/// left as the cell set it.
228	pub fn run_cell(
229	    flavor: Flavor,
230	    dur: Duration,
231	    pin: Option<(usize, usize)>,
232	    depth: u32,
233	) -> CellResult {
234	    match pin {
235	        Some((main_cpu, _)) => pin_to_cpu(main_cpu),
236	        None => unpin_current(),
237	    }
238	    #[cfg(target_os = "linux")]
239	    let fills = Fills::open();
240	    let worker = pin.map(|(_, w)| w);
241	    let probes = match flavor {
242	        Flavor::Spsc => run_spsc(dur, worker, depth),
243	        Flavor::SpscV1 => run_spsc_v1(dur, worker, depth),
244	        Flavor::SpscV2 => run_spsc_v2(dur, worker, depth),
245	        Flavor::Mpsc => run_mpsc(dur, worker, depth),
246	    };
247	    #[cfg(target_os = "linux")]
248	    let fills = fills.and_then(Fills::finish);
249	    #[cfg(not(target_os = "linux"))]
250	    let fills = None;
251	    let rts = probes[0].count();
252	    CellResult { probes, rts, fills }
253	}
254	
255	/// Define an SPSC cell body over the ring at `$ring`, its
256	/// regions sized by `$size(slot_size, depth)`: two rings, both
257	/// ends `reserve_slot_with` under the [`spin`] policy (recv
258	/// sites instrumented). The SPSC versions share the endpoint
259	/// surface and differ by path, so one body serves them all and
260	/// the A/B measures the protocol alone.
261	macro_rules! spsc_cell {
262	    ($name:ident, $ring:path, $size:path, $flavor:expr) => {
263	        fn $name(dur: Duration, worker_cpu: Option<usize>, depth: u32) -> [TProbe; 8] {
264	            use $ring as Ring;
265	            let slot = CACHE_LINE_SIZE as u32;
266	            let mut req_region = LineBuf::new($size(slot, depth));
267	            let mut resp_region = LineBuf::new($size(slot, depth));
268	            let (mut req_tx, mut req_rx) = Ring::init(req_region.as_mut_bytes(), slot, depth)
269	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
270	                .split();
271	            let (mut resp_tx, mut resp_rx) = Ring::init(resp_region.as_mut_bytes(), slot, depth)
272	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
273	                .split();
274	
275	            std::thread::scope(|s| {
276	                let worker = s.spawn(move || {
277	                    if let Some(cpu) = worker_cpu {
278	                        pin_to_cpu(cpu);
279	                    }
280	                    let mut recv = RecvProbes::new($flavor, "worker");
281	                    let mut send_probe = TProbe::new(&format!(
282	                        "{} worker send (reserve+commit)",
283	                        $flavor.as_str()
284	                    ));
285	                    loop {
286	                        let v = instrumented_recv(&mut recv, |attempts, spin_start| {
287	                            let slot = req_rx
288	                                .reserve_slot_with::<u64>(|a| {
289	                                    if a == 0 {
290	                                        *spin_start = ticks::read_ticks();
291	                                    }
292	                                    *attempts = a + 1;
293	                                    core::hint::spin_loop();
294	                                    true
295	                                })
296	                                .expect("spin never gives up");
297	                            let v = *slot;
298	                            slot.release();
299	                            v
300	                        });
301	                        if v == STOP {
302	                            break;
303	                        }
304	                        let s = ticks::read_ticks();
305	                        let mut slot = resp_tx
306	                            .reserve_slot_with::<u64>(spin)
307	                            .expect("spin never gives up");
308	                        *slot = v;
309	                        slot.commit();
310	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
311	                    }
312	                    (recv, send_probe)
313	                });
314	
315	                let mut send_probe =
316	                    TProbe::new(&format!("{} main send (reserve+commit)", $flavor.as_str()));
317	                let mut recv = RecvProbes::new($flavor, "main");
318	                drive(
319	                    dur,
320	                    |v| {
321	                        let s = ticks::read_ticks();
322	                        let mut slot = req_tx
323	                            .reserve_slot_with::<u64>(spin)
324	                            .expect("spin never gives up");
325	                        *slot = v;
326	                        slot.commit();
327	                        send_probe.record(ticks::read_ticks().wrapping_sub(s));
328	                    },
329	                    || {
330	                        instrumented_recv(&mut recv, |attempts, spin_start| {
331	                            let slot = resp_rx
332	                                .reserve_slot_with::<u64>(|a| {
333	                                    if a == 0 {
334	                                        *spin_start = ticks::read_ticks();
335	                                    }
336	                                    *attempts = a + 1;
337	                                    core::hint::spin_loop();
338	                                    true
339	                                })
340	                                .expect("spin never gives up");
341	                            let v = *slot;
342	                            slot.release();
343	                            v
344	                        })
345	                    },
346	                );
347	                let mut slot = req_tx
348	                    .reserve_slot_with::<u64>(spin)
349	                    .expect("spin never gives up");
350	                *slot = STOP;
351	                slot.commit();
352	                let (worker_recv, worker_send) = worker.join().expect("worker panicked");
353	                [
354	                    send_probe,
355	                    worker_recv.phase,
356	                    worker_recv.spin,
357	                    worker_recv.attempts,
358	                    worker_send,
359	                    recv.phase,
360	                    recv.spin,
361	                    recv.attempts,
362	                ]
363	            })
364	        }
365	    };
366	}
367	
368	spsc_cell!(
369	    run_spsc,
370	    zc_ring_x1::spsc::v0::Ring,
371	    v0_region_size,
372	    Flavor::Spsc
373	);
374	spsc_cell!(
375	    run_spsc_v1,
376	    zc_ring_x1::spsc::v1::Ring,
377	    zc_ring_x1::spsc::v1::region_size,
378	    Flavor::SpscV1
379	);
380	spsc_cell!(
381	    run_spsc_v2,
382	    zc_ring_x1::spsc::v2::Ring,
383	    zc_ring_x1::spsc::v2::region_size,
384	    Flavor::SpscV2
385	);
386	
387	/// MPSC cell body: two `MpscRing`s at 1p/1c — producers
388	/// `send_with` (closure fill), the consumer `reserve_slot_with`,
389	/// both under the [`spin`] policy (recv sites instrumented).
390	fn run_mpsc(dur: Duration, worker_cpu: Option<usize>, depth: u32) -> [TProbe; 8] {
391	    let slot = CACHE_LINE_SIZE as u32;
392	    let mut req_region = LineBuf::new(mpsc_region_size(slot, depth));
393	    let mut resp_region = LineBuf::new(mpsc_region_size(slot, depth));
394	    let (req_tx, mut req_rx) = MpscRing::init(req_region.as_mut_bytes(), slot, depth)
395	        .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
396	        .split();
397	    let (resp_tx, mut resp_rx) = MpscRing::init(resp_region.as_mut_bytes(), slot, depth)
398	        .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
399	        .split();
400	
401	    std::thread::scope(|s| {
402	        let worker = s.spawn(move || {
403	            if let Some(cpu) = worker_cpu {
404	                pin_to_cpu(cpu);
405	            }
406	            let mut recv = RecvProbes::new(Flavor::Mpsc, "worker");
407	            let mut send_probe = TProbe::new("mpsc worker send (send_with)");
408	            loop {
409	                let v = instrumented_recv(&mut recv, |attempts, spin_start| {
410	                    let slot = req_rx
411	                        .reserve_slot_with::<u64>(|a| {
412	                            if a == 0 {
413	                                *spin_start = ticks::read_ticks();
414	                            }
415	                            *attempts = a + 1;
416	                            core::hint::spin_loop();
417	                            true
418	                        })
419	                        .expect("spin never gives up");
420	                    let v = *slot;
421	                    slot.release();
422	                    v
423	                });
424	                if v == STOP {
425	                    break;
426	                }
427	                let s = ticks::read_ticks();
428	                resp_tx
429	                    .send_with::<u64>(spin, |m| *m = v)
430	                    .expect("spin never gives up");
431	                send_probe.record(ticks::read_ticks().wrapping_sub(s));
432	            }
433	            (recv, send_probe)
434	        });
435	
436	        let mut send_probe = TProbe::new("mpsc main send (send_with)");
437	        let mut recv = RecvProbes::new(Flavor::Mpsc, "main");
438	        drive(
439	            dur,
440	            |v| {
441	                let s = ticks::read_ticks();
442	                req_tx
443	                    .send_with::<u64>(spin, |m| *m = v)
444	                    .expect("spin never gives up");
445	                send_probe.record(ticks::read_ticks().wrapping_sub(s));
446	            },
447	            || {
448	                instrumented_recv(&mut recv, |attempts, spin_start| {
449	                    let slot = resp_rx
450	                        .reserve_slot_with::<u64>(|a| {
451	                            if a == 0 {
452	                                *spin_start = ticks::read_ticks();
453	                            }
454	                            *attempts = a + 1;
455	                            core::hint::spin_loop();
456	                            true
457	                        })
458	                        .expect("spin never gives up");
459	                    let v = *slot;
460	                    slot.release();
461	                    v
462	                })
463	            },
464	        );
465	        req_tx
466	            .send_with::<u64>(spin, |m| *m = STOP)
467	            .expect("spin never gives up");
468	        let (worker_recv, worker_send) = worker.join().expect("worker panicked");
469	        [
470	            send_probe,
471	            worker_recv.phase,
472	            worker_recv.spin,
473	            worker_recv.attempts,
474	            worker_send,
475	            recv.phase,
476	            recv.spin,
477	            recv.attempts,
478	        ]
479	    })
480	}
481	
482	/// One streaming cell's outcome.
483	pub struct StreamResult {
484	    /// Messages the consumer received, the stop sentinel not
485	    /// counted.
486	    pub msgs: u64,
487	    /// Wall-clock seconds from the first send to the consumer
488	    /// seeing the stop sentinel.
489	    pub secs: f64,
490	    /// Fill counters over the whole stream, when the platform
491	    /// provides them.
492	    pub fills: Option<FillCounts>,
493	}
494	
495	/// Messages between the producer's wall-clock checks, as
496	/// `drive` spaces its checks.
497	const STREAM_CHECK_EVERY: u64 = 4096;
498	
499	/// Run one streaming cell: open the fill counters, stream a
500	/// counter for `dur` at `flavor` and ring `depth` from a
501	/// producer thread on `pin.0` to a consumer thread on `pin.1`,
502	/// and return the count, the elapsed time, and the counters.
503	///
504	/// - Both ends are spawned threads that pin themselves, as the
505	///   demo's streams do, so the calling thread's affinity is
506	///   untouched and the two sides start alike.
507	/// - The producer sends as fast as the ring admits under the
508	///   [`spin`] policy, so the ring sits full whenever the
509	///   consumer is the slower side, and the consumer asserts the
510	///   counter's order.
511	/// - The elapsed time ends when the consumer has seen the stop
512	///   sentinel, so the last message's drain is inside it.
513	pub fn run_stream(
514	    flavor: Flavor,
515	    dur: Duration,
516	    pin: Option<(usize, usize)>,
517	    depth: u32,
518	) -> StreamResult {
519	    unpin_current();
520	    #[cfg(target_os = "linux")]
521	    let fills = Fills::open();
522	    let (msgs, secs) = match flavor {
523	        Flavor::Spsc => stream_spsc(dur, pin, depth),
524	        Flavor::SpscV1 => stream_spsc_v1(dur, pin, depth),
525	        Flavor::SpscV2 => stream_spsc_v2(dur, pin, depth),
526	        Flavor::Mpsc => stream_mpsc(dur, pin, depth),
527	    };
528	    #[cfg(target_os = "linux")]
529	    let fills = fills.and_then(Fills::finish);
530	    #[cfg(not(target_os = "linux"))]
531	    let fills = None;
532	    StreamResult { msgs, secs, fills }
533	}
534	
535	/// The consumer side of a streaming cell: drain `recv` until
536	/// the stop sentinel, asserting the counter's order, and
537	/// return the count received.
538	fn drain_stream(mut recv: impl FnMut() -> u64) -> u64 {
539	    let mut expected: u64 = 0;
540	    loop {
541	        let v = recv();
542	        if v == STOP {
543	            return expected;
544	        }
545	        assert_eq!(v, expected, "stream order broken");
546	        expected += 1;
547	    }
548	}
549	
550	/// Define an SPSC streaming cell body over the ring at `$ring`,
551	/// its region sized by `$size(slot_size, depth)`: one ring,
552	/// the producer spawned on `pin.0`, the consumer on `pin.1`.
553	/// Returns the messages moved and the seconds.
554	macro_rules! spsc_stream {
555	    ($name:ident, $ring:path, $size:path) => {
556	        fn $name(dur: Duration, pin: Option<(usize, usize)>, depth: u32) -> (u64, f64) {
557	            use $ring as Ring;
558	            let slot = CACHE_LINE_SIZE as u32;
559	            let mut region = LineBuf::new($size(slot, depth));
560	            let (mut tx, mut rx) = Ring::init(region.as_mut_bytes(), slot, depth)
561	                .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
562	                .split();
563	            let start = Instant::now();
564	            let msgs = std::thread::scope(|s| {
565	                s.spawn(move || {
566	                    if let Some((p, _)) = pin {
567	                        pin_to_cpu(p);
568	                    }
569	                    let mut counter: u64 = 0;
570	                    loop {
571	                        for _ in 0..STREAM_CHECK_EVERY {
572	                            let mut slot = tx
573	                                .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
574	                                .expect("spin never gives up");
575	                            *slot = counter;
576	                            slot.commit();
577	                            counter += 1;
578	                        }
579	                        if start.elapsed() >= dur {
580	                            break;
581	                        }
582	                    }
583	                    let mut slot = tx
584	                        .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
585	                        .expect("spin never gives up");
586	                    *slot = STOP;
587	                    slot.commit();
588	                });
589	                let consumer = s.spawn(move || {
590	                    if let Some((_, c)) = pin {
591	                        pin_to_cpu(c);
592	                    }
593	                    drain_stream(|| {
594	                        let slot = rx
595	                            .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
596	                            .expect("spin never gives up");
597	                        let v = *slot;
598	                        slot.release();
599	                        v
600	                    })
601	                });
602	                consumer.join().expect("consumer panicked")
603	            });
604	            (msgs, start.elapsed().as_secs_f64())
605	        }
606	    };
607	}
608	
609	spsc_stream!(stream_spsc, zc_ring_x1::spsc::v0::Ring, v0_region_size);
610	spsc_stream!(
611	    stream_spsc_v1,
612	    zc_ring_x1::spsc::v1::Ring,
613	    zc_ring_x1::spsc::v1::region_size
614	);
615	spsc_stream!(
616	    stream_spsc_v2,
617	    zc_ring_x1::spsc::v2::Ring,
618	    zc_ring_x1::spsc::v2::region_size
619	);
620	
621	/// MPSC streaming cell body: one `MpscRing` at 1p/1c, the
622	/// producer `send_with` spawned on `pin.0`, the consumer on
623	/// `pin.1`. Returns the messages moved and the seconds.
624	fn stream_mpsc(dur: Duration, pin: Option<(usize, usize)>, depth: u32) -> (u64, f64) {
625	    let slot = CACHE_LINE_SIZE as u32;
626	    let mut region = LineBuf::new(mpsc_region_size(slot, depth));
627	    let (tx, mut rx) = MpscRing::init(region.as_mut_bytes(), slot, depth)
628	        .unwrap() // OK: the region is sized by mpsc_region_size and line-aligned
629	        .split();
630	    let start = Instant::now();
631	    let msgs = std::thread::scope(|s| {
632	        s.spawn(move || {
633	            if let Some((p, _)) = pin {
634	                pin_to_cpu(p);
635	            }
636	            let mut counter: u64 = 0;
637	            loop {
638	                for _ in 0..STREAM_CHECK_EVERY {
639	                    tx.send_with::<u64>(zc_ring_x1::policy::spin, |m| *m = counter)
640	                        .expect("spin never gives up");
641	                    counter += 1;
642	                }
643	                if start.elapsed() >= dur {
644	                    break;
645	                }
646	            }
647	            tx.send_with::<u64>(zc_ring_x1::policy::spin, |m| *m = STOP)
648	                .expect("spin never gives up");
649	        });
650	        let consumer = s.spawn(move || {
651	            if let Some((_, c)) = pin {
652	                pin_to_cpu(c);
653	            }
654	            drain_stream(|| {
655	                let slot = rx
656	                    .reserve_slot_with::<u64>(zc_ring_x1::policy::spin)
657	                    .expect("spin never gives up");
658	                let v = *slot;
659	                slot.release();
660	                v
661	            })
662	        });
663	        consumer.join().expect("consumer panicked")
664	    });
665	    (msgs, start.elapsed().as_secs_f64())
666	}
